"""
json_path_projection.py

Provides extract_fields for projecting values out of nested dicts/lists
using dot-separated paths with optional integer list indexes.
"""

_MISSING = object()


def _resolve_path(record, path, default):
    """Walk *path* segments into *record*, returning *default* on any miss."""
    node = record
    for segment in path.split("."):
        if node is None:
            return default
        if isinstance(node, list):
            try:
                index = int(segment)
            except ValueError:
                return default
            if index < 0 or index >= len(node):
                return default
            node = node[index]
        elif isinstance(node, dict):
            if segment not in node:
                return default
            node = node[segment]
        else:
            return default
    return node


def extract_fields(record: dict, paths: dict, default=None, required=None) -> dict:
    """
    Extract values from *record* using dot-separated *paths*.

    Parameters
    ----------
    record   : the source nested structure (dict at the top level)
    paths    : mapping of output_key -> dot-separated path string
    default  : value used when a path cannot be resolved
    required : optional set of output keys whose paths must resolve;
               if a required key cannot be resolved, KeyError is raised
               instead of returning default

    Returns
    -------
    dict mapping each output key to the resolved (or default) value.
    """
    if not isinstance(record, dict):
        raise TypeError(f"record must be a dict, got {type(record).__name__!r}")
    if not isinstance(paths, dict):
        raise TypeError(f"paths must be a dict, got {type(paths).__name__!r}")
    if required is not None and not isinstance(required, set):
        raise TypeError(f"required must be a set or None, got {type(required).__name__!r}")

    result = {}
    for output_key, path in paths.items():
        value = _resolve_path(record, path, _MISSING)
        if value is _MISSING:
            if required is not None and output_key in required:
                raise KeyError(output_key)
            result[output_key] = default
        else:
            result[output_key] = value
    return result

